output.hcl:
provider "google" {
  project = var.project_id
  region  = var.region
}

provider "google-beta" {
  project = var.project_id
  region  = var.region
}

resource "google_service_account" "app" {
  account_id   = "${var.app_name}-sa"
  display_name = "${var.app_name} Cloud Run Service Account"
}

resource "google_project_iam_member" "sa_firestore" {
  project = var.project_id
  role    = "roles/datastore.user"
  member  = "serviceAccount:${google_service_account.app.email}"
}

resource "google_project_iam_member" "sa_storage" {
  project = var.project_id
  role    = "roles/storage.objectAdmin"
  member  = "serviceAccount:${google_service_account.app.email}"
}

resource "google_project_iam_member" "sa_secrets" {
  project = var.project_id
  role    = "roles/secretmanager.secretAccessor"
  member  = "serviceAccount:${google_service_account.app.email}"
}

resource "google_firebase_hosting_site" "frontend" {
  project  = var.project_id
  site_id  = var.app_name
  provider = google-beta
}

resource "google_firebase_hosting_version" "frontend" {
  site_id  = google_firebase_hosting_site.frontend.site_id
  provider = google-beta

  config {
    rewrites {
      glob = "/api/**"
      run {
        service_id = google_cloud_run_v2_service.app.name
        region     = var.region
      }
    }
    rewrites {
      glob = "**"
      path = "/index.html"
    }
  }
}

resource "google_firebase_hosting_release" "frontend" {
  site_id      = google_firebase_hosting_site.frontend.site_id
  version_name = google_firebase_hosting_version.frontend.name
  provider     = google-beta
}

resource "google_cloud_run_v2_service_iam_member" "public" {
  name     = google_cloud_run_v2_service.app.name
  location = var.region
  role     = "roles/run.invoker"
  member   = "allUsers"
}

resource "google_firestore_database" "main" {
  name        = "(default)"
  location_id = var.region
  type        = "FIRESTORE_NATIVE"
}

resource "google_identity_platform_config" "auth" {
  project = var.project_id

  sign_in {
    allow_duplicate_emails = false
    email {
      enabled           = true
      password_required = true
    }
  }
}

resource "google_storage_bucket" "uploads" {
  name          = "${var.app_name}-uploads"
  location      = var.region
  force_destroy = false

  uniform_bucket_level_access = true
}

resource "google_secret_manager_secret" "weather_weather-key" {
  secret_id = "${var.app_name}-weather-key"
  replication {
    auto {}
  }
}

output "backend_url" {
  value = google_cloud_run_v2_service.app.uri
}

output "frontend_url" {
  value = "https://${var.app_name}.web.app"
}

output "service_account_email" {
  value = google_service_account.app.email
}

resource "google_redis_instance" "events" {
  name           = "${var.app_name}-events"
  tier           = "BASIC"
  memory_size_gb = 1
  region         = var.region

  redis_configs = {
    maxmemory-policy = "allkeys-lru"
  }
}

output "redis_host" {
  value = google_redis_instance.events.host
}

resource "google_vpc_access_connector" "main" {
  name          = "${var.app_name}-vpc"
  region        = var.region
  network       = "default"
  ip_cidr_range = "10.8.0.0/28"
  min_instances = 2
  max_instances = 3
}

resource "google_cloud_scheduler_job" "tick" {
  name     = "${var.app_name}-tick"
  region   = var.region
  schedule = "*/1 * * * *"

  http_target {
    uri         = "${google_cloud_run_v2_service.app.uri}/api/tick"
    http_method = "POST"

    oidc_token {
      service_account_email = google_service_account.app.email
    }
  }
}

resource "google_cloud_run_v2_service" "app" {
  name     = var.app_name
  location = var.region

  template {
    service_account = google_service_account.app.email
    containers {
      image = var.container_image

      resources {
        limits = {
          cpu    = "1"
          memory = "512Mi"
        }
      }

      env {
        name  = "NODE_ENV"
        value = "production"
      }

      env {
        name  = "FIREBASE_PROJECT_ID"
        value = var.project_id
      }

      env {
        name  = "FIREBASE_DATABASE_ID"
        value = "(default)"
      }

      env {
        name  = "FIREBASE_STORAGE_BUCKET"
        value = "${var.app_name}-uploads"
      }

      env {
        name  = "REDIS_HOST"
        value = google_redis_instance.events.host
      }

      env {
        name  = "REDIS_PORT"
        value = google_redis_instance.events.port
      }

      env {
        name = "WEATHER_KEY"
        value_source {
          secret_key_ref {
            secret  = google_secret_manager_secret.weather_weather-key.secret_id
            version = "latest"
          }
        }
      }
    }

    scaling {
      min_instance_count = 0
      max_instance_count = 10
    }

    vpc_access {
      connector = google_vpc_access_connector.main.id
      egress    = "PRIVATE_RANGES_ONLY"
    }
  }

  traffic {
    type    = "TRAFFIC_TARGET_ALLOCATION_TYPE_LATEST"
    percent = 100
  }
}

output.variables:
variable "project_id" {
  description = "GCP project ID"
  type        = string
}

variable "region" {
  description = "GCP region"
  type        = string
  default     = "europe-west4"
}

variable "app_name" {
  description = "Application name"
  type        = string
  default     = "tiny"
}

variable "container_image" {
  description = "Docker container image for the backend"
  type        = string
}

variable "db_password" {
  description = "Database password for Cloud SQL (only required when Postgres is used)"
  type        = string
  sensitive   = true
  default     = ""
}

